async function publishCommunityPost(){const text=communityDraft.value.trim();if(!text||postingCommunity.value)return;if(!verified.value){modal.value='发布社区动态';return}postingCommunity.value=true;try{if(backendReady.value){const {post}=await apiRequest('/community/posts',{method:'POST',body:JSON.stringify({text,type:communityDraftType.value})});communityPosts.value=communityPosts.value.filter(item=>item.id!==post.id);communityPosts.value.unshift(post);communityDraft.value='';flash('动态已发布，社区成员现在都能看到');return}communityPosts.value.unshift({id:`post-${Date.now()}`,author:me.value.name,tone:me.value.avatarTone,type:communityDraftType.value,time:'刚刚',text,likes:0,liked:false,comments:[]});communityDraft.value='';flash('动态已发布（仅保存在本机原型）')}catch(error){flash(error.message)}finally{postingCommunity.value=false}}
