function upsertApiUser(user){if(!user||user.id===backendUserId.value)return;const index=users.value.findIndex(item=>item.id===user.id);if(index<0)users.value.unshift(mapApiUser(user));else users.value[index]={...users.value[index],...mapApiUser(user)}}
function attachCommunityEvents(){communityEvents?.close();if(!verified.value||!backendReady.value)return;communityEvents=new EventSource('/api/events/stream');communityEvents.addEventListener('post-created',event=>{const {post}=JSON.parse(event.data);if(post&&!communityPosts.value.some(item=>item.id===post.id))communityPosts.value.unshift(post)});communityEvents.addEventListener('comment-created',event=>{const {postId,comment}=JSON.parse(event.data),post=communityPosts.value.find(item=>item.id===postId);if(post&&comment&&!post.comments.some(item=>item.id===comment.id))post.comments.push(comment)});communityEvents.addEventListener('like-updated',event=>{const {postId,likes}=JSON.parse(event.data),post=communityPosts.value.find(item=>item.id===postId);if(post)post.likes=likes});communityEvents.addEventListener('listing-created',event=>{const {item}=JSON.parse(event.data);if(item&&!listings.value.some(listing=>listing.id===item.id))listings.value.unshift(item)});communityEvents.addEventListener('presence',event=>upsertApiUser(JSON.parse(event.data).user));communityEvents.addEventListener('profile-updated',event=>upsertApiUser(JSON.parse(event.data).user));communityEvents.addEventListener('message-created',event=>{const payload=JSON.parse(event.data);if(payload.recipientId!==backendUserId.value)return;const peer=users.value.find(user=>user.id===payload.senderId);if(!peer)return;const thread=chatThreads.value[peer.name]??={messages:[],unread:0};const message={...payload.message,from:'peer'};if(!thread.messages.some(item=>item.id===message.id))thread.messages.push(message);if(activeChatUser.value?.id===peer.id&&railTab.value==='chat'&&railOpen.value)nextTick(scrollChatToBottom);else thread.unread=(thread.unread||0)+1;persistChats()})}
