const guideStorageKey='nailong-campus-first-visit-v1';
const guideStep=ref(-1);
const guideSteps=[
 {title:'先选一个校园地点',body:'点地图上的地点标记，查看建筑介绍、实景资料和可进行的互动。',action:'查看图书馆',run:()=>selectSpot(spots[0])},
 {title:'操控奶龙走进校园',body:'切到操控模式后，点击步道移动；点建筑会规划入口路线。',action:'开始操控',run:()=>enterControl()},
 {title:'看看附近有哪些同学',body:'打开同学面板查看演示资料。活跃状态可接收邀约，消沉状态会暂停邀约。',action:'查看附近同学',run:()=>{leaveControl();showNearby()}},
 {title:'去活动广场找队友',body:'系统推荐活动为主要邀约来源，你可以自行决定参加或跳过。当前活动角色与报名均为本机演示。',action:'打开活动广场',run:()=>{leaveControl();page.value='events';railOpen.value=false}}
];
const currentGuideStep=computed(()=>guideSteps[guideStep.value]||null);
function startGuide(){guideStep.value=0;page.value='map';menuOpen.value=false;railOpen.value=false;}
function advanceGuide(){const current=currentGuideStep.value;if(!current)return;current.run();if(guideStep.value>=guideSteps.length-1){guideStep.value=-1;try{localStorage.setItem(guideStorageKey,'done')}catch{};flash('体验引导已完成，接下来可以自由探索校园');return}guideStep.value++}
function dismissGuide(){guideStep.value=-1;try{localStorage.setItem(guideStorageKey,'done')}catch{};}
function resetMap(){if(controlMode.value)leaveControl();gameMap.value?.reset();flash('视点已回到校园全景')}
function enterControl(){if(page.value!=='map')page.value='map';controlMode.value=true;railOpen.value=false;menuOpen.value=false;nextTick(()=>{if(!playerSelected.value)gameMap.value?.selectPlayer()});}
function leaveControl(){gameMap.value?.stopPlayer();if(indoorBuilding.value)gameMap.value?.exitBuilding();indoorBuilding.value=null;controlMode.value=false;playerSelected.value=false;playerMoving.value=false;playerDestination.value='';enteringBuilding.value='';helpOpen.value=false;}
function ensurePlayerSelected(){if(!playerSelected.value)gameMap.value?.selectPlayer()}
function sendTo(x,z,label){enterControl();ensurePlayerSelected();playerDestination.value=label;const accepted=gameMap.value?.movePlayer(x,z);if(accepted===false)flash('这里暂时无法抵达，请换一个入口或步道位置');else if(accepted?.blocked){playerMoving.value=false;playerDestination.value='';flash('目标点暂时无法通过步道抵达，已先走出建筑');}else{if(accepted&&typeof accepted==='object'){if(pendingClass.value){pendingClass.value.x=accepted.x;pendingClass.value.z=accepted.z}if(currentActivity.value?.status==='正在前往'){currentActivity.value.x=accepted.x;currentActivity.value.z=accepted.z}}playerMoving.value=true;flash(`已下达移动命令：前往${label}`)}}
let lastPositionSave=0,lastPresenceSync=0;
async function syncPresence(){if(!backendReady.value||!verified.value||Date.now()-lastPresenceSync<3000)return;lastPresenceSync=Date.now();const nearest=spots.reduce((best,spot)=>Math.hypot(me.value.x-spot.x,me.value.z-spot.z)<Math.hypot(me.value.x-best.x,me.value.z-best.z)?spot:best,spots[0]);try{await apiRequest('/presence',{method:'POST',body:JSON.stringify({x:me.value.x,z:me.value.z,area:nearest.name,status:playerMoving.value?`正在前往${playerDestination.value||'目的地'}`:'正在校园活动'})})}catch(error){console.warn('Presence sync failed:',error.message)}}
function onRoleEvent(event){if(event.type==='playerClicked'){enterControl();return}if(event.type==='selected'){playerSelected.value=event.selected;return}if(event.type==='buildingTargeted'){flash(`已选中${event.building} · 正在规划入口路线`);return}if(event.type==='entering'){enteringBuilding.value=event.building;playerDestination.value=`${event.building}入口`;playerMoving.value=true;return}if(event.type==='entryCancelled'){enteringBuilding.value='';return}if(event.type==='entered'){indoorBuilding.value=event.building;enteringBuilding.value='';me.value.x=event.x;me.value.z=event.z;playerMoving.value=false;playerDestination.value='';railTab.value='place';railOpen.value=entryShowDetails.value;if(entryShowDetails.value)nextTick(()=>document.querySelector('.right-rail')?.scrollTo({top:0,behavior:'smooth'}));flash(`已进入${event.building} · 当前仍显示建筑外观`);return}if(event.type==='exited'){indoorBuilding.value=null;enteringBuilding.value='';me.value.x=event.x;me.value.z=event.z;persistPosition();flash('已走出建筑，回到入口外');return}if(event.type==='hint'){flash(event.message);return}if(event.type==='blocked'){playerMoving.value=false;flash('当前地点无法通过步道抵达');return}if(event.type==='cancel'){gameMap.value?.stopPlayer();flash('已取消移动命令');return}if(event.type==='position'||event.type==='arrived'||event.type==='stopped'){me.value.x=event.x;me.value.z=event.z;if((event.type!=='position'||Date.now()-lastPositionSave>1200)&&!indoorBuilding.value){persistPosition();lastPositionSave=Date.now();}if(event.type==='arrived'||event.type==='stopped')syncPresence()}if(event.type==='moving'){playerMoving.value=true;if(event.entering)enteringBuilding.value=event.entering;if(!playerDestination.value)playerDestination.value=`地图点 ${Math.round(event.x)}, ${Math.round(event.z)}`;}if(event.type==='stopped'){playerMoving.value=false;playerDestination.value='';enteringBuilding.value='';}if(event.type==='arrived'){playerMoving.value=false;playerDestination.value='';if(currentActivity.value){currentActivity.value.status='已到达集合点';flash(`已到达${currentActivity.value.place}，可以开始活动`)}else if(!indoorBuilding.value&&!enteringBuilding.value)flash('已到达目的地');}}
function goInside(building,showDetails=true){entryShowDetails.value=showDetails;enterControl();campusSelection.value=building;active.value=building.name;selectedUser.value=null;railTab.value='place';railOpen.value=showDetails;ensurePlayerSelected();enteringBuilding.value=building.name;playerDestination.value=`${building.name}入口`;const result=gameMap.value?.enterBuilding(building.id);if(result===false){enteringBuilding.value='';playerDestination.value='';playerMoving.value=false;if(pendingClass.value?.buildingId===building.id)pendingClass.value=null;if(pendingExam.value)pendingExam.value=false;flash('这里暂时没有可进入的入口');return}playerMoving.value=true;if(result&&typeof result==='object')flash(`已规划${building.name}入口路线 · 奶龙将走到门口后进入`);}
function leaveInterior(){gameMap.value?.exitBuilding()}
function go(spot){campusSelection.value=null;active.value=spot.name;sendTo(spot.x,spot.z+12,spot.name)}
function study(){me.value.prep=Math.min(100,me.value.prep+12);me.value.energy=Math.max(0,me.value.energy-7);flash('专注学习完成，考试准备度 +12')}
function attend(c){if(c.status==='已完成'||c.status==='上课中')return;if(indoorBuilding.value!==c.building){const building=buildings.find(item=>item.id===c.buildingId);if(!building){flash('课程地点资料暂不可用');return}pendingClass.value=c;page.value='map';campusSelection.value=building;active.value=building.name;goInside(building);flash(`奶龙正在前往${c.room}；进入公共教学楼后即可开始上课`);return}if(c.status!=='已到教室'){c.status='已到教室';flash(`已进入${c.building}，可以开始${c.room}`);return}c.status='上课中';c.endsAt=Date.now()+45000;c.remaining=45;flash('已开始上课，请留在公共教学楼直到课程结束');const timer=setInterval(()=>{if(indoorBuilding.value!==c.building){clearInterval(timer);c.status='已中断';c.remaining=0;c.endsAt=null;flash('离开教学楼，课程已中断；本次不计出勤，可重新进入继续');return}c.remaining=Math.max(0,Math.ceil((c.endsAt-Date.now())/1000));if(c.remaining<=0){clearInterval(timer);c.status='已完成';c.endsAt=null;me.value.att=Math.min(100,me.value.att+3);me.value.energy=Math.max(0,me.value.energy-4);flash('课程结束，已计入原型出勤与平时分')}},500)}
let examTimer=null,activityTimer=null;
function startExamTimer(){if(exam.value.score||exam.value.status==='考试中')return;if(indoorBuilding.value!=='图书馆'){flash('请先进入图书馆原型考场');return}exam.value.status='考试中';exam.value.endsAt=Date.now()+30000;exam.value.remaining=30;flash('阶段测验开始，请留在图书馆考场完成 30 秒原型答题');clearInterval(examTimer);examTimer=setInterval(()=>{if(indoorBuilding.value!=='图书馆'){clearInterval(examTimer);exam.value.status='待考';exam.value.endsAt=null;exam.value.remaining=0;flash('已离开图书馆考场，测验暂停；返回图书馆可继续')}else{exam.value.remaining=Math.max(0,Math.ceil((exam.value.endsAt-Date.now())/1000));if(exam.value.remaining<=0){clearInterval(examTimer);exam.value.status='已完成';exam.value.endsAt=null;exam.value.score=Math.min(100,Math.round(45+me.value.prep*.45+me.value.att*.1));me.value.final=exam.value.score;flash(`测验完成：${exam.value.score} 分 · ${gradeStatus.value}`)} }},250)}
function sitExam(){if(exam.value.score)return;if(exam.value.status==='考试中'){flash(`测验进行中，还需 ${exam.value.remaining} 秒`);return}if(indoorBuilding.value==='图书馆'){startExamTimer();return}const library=buildings.find(building=>building.id==='01');if(!library){flash('图书馆考场资料暂不可用');return}pendingExam.value=true;page.value='map';campusSelection.value=library;active.value=library.name;goInside(library);flash('阶段测验需进入图书馆原型考场，奶龙正在前往')}
watch(()=>[indoorBuilding.value,pendingExam.value,pendingClass.value?.building],([building,examPending,classBuilding])=>{if(examPending&&building==='图书馆'){pendingExam.value=false;startExamTimer()}if(classBuilding&&building===classBuilding){pendingClass.value.status='已到教室';pendingClass.value=null;flash(`已进入${building}，返回课表即可开始上课`)}});
function gated(action){if(!verified.value){modal.value=action;return}flash(backendReady.value?'该项操作暂未开放。':'已加入，更多互动将在真实校内验证接入后开放')}
function openListingForm(){if(!verified.value){modal.value='发布闲置';return}listingDraft.value={title:'',tag:'生活好物',price:'',place:'',description:''};modal.value='listing-create'}
async function createListing(){if(postingListing.value)return;const draft=listingDraft.value;if(!draft.title.trim()||!draft.place.trim()||!Number.isFinite(Number(draft.price))){flash('请填写商品名称、价格和交接地点');return}postingListing.value=true;try{if(backendReady.value){const {item}=await apiRequest('/market/items',{method:'POST',body:JSON.stringify(draft)});if(!listings.value.some(existing=>existing.id===item.id))listings.value.unshift(item)}else{listings.value.unshift({id:`list-${Date.now()}`,title:draft.title.trim(),description:draft.description.trim(),tag:draft.tag,price:`¥ ${Number(draft.price)}`,amount:Number(draft.price),seller:me.value.name,sellerId:backendUserId.value,sellerTone:me.value.avatarTone,place:draft.place.trim(),color:'#e9e9d9'})}modal.value='';communityTab.value='market';flash(backendReady.value?'闲置已发布，社区成员现在都能看到':'已发布到本机演示列表')}catch(error){flash(error.message)}finally{postingListing.value=false}}
function contactSeller(item){if(!verified.value){modal.value='联系卖家';return}const seller=users.value.find(user=>user.id===item.sellerId)||users.value.find(user=>user.name===item.seller);if(!seller){flash('卖家账号暂不可用');return}openChat(seller)}
async function verify(){try{if(backendReady.value){const {user}=await apiRequest('/auth/demo',{method:'POST',body:JSON.stringify({name:me.value.name,avatarTone:me.value.avatarTone,faculty:me.value.faculty,year:me.value.year,bio:me.value.bio,interests:me.value.interests,socialState:me.value.socialState,visibility:me.value.visibility,x:me.value.x,z:me.value.z})});backendUserId.value=user.id;verified.value=true;modal.value='';const people=await apiRequest('/users');users.value=people.users.map(mapApiUser);attachCommunityEvents();await apiRequest('/presence',{method:'POST',body:JSON.stringify({x:me.value.x,z:me.value.z,area:'校园入口',status:'刚刚来到校园'})});flash('演示账号已连接本地社区后端；这不代表真实校内认证');return}verified.value=true;modal.value='';flash('本机模拟身份已开启；后端暂不可用，内容仅保存在本机')}catch(error){flash(error.message)}}
function contact(user){selectedUser.value=user;railTab.value='nearby';railOpen.value=true;modal.value=''}
function selectSpot(spot){campusSelection.value=null;selectedUser.value=null;active.value=spot.name;railTab.value='place';railOpen.value=true}
function showNearby(){selectedUser.value=null;railTab.value='nearby';railOpen.value=true}
function closeRailOnBlank(event){if(!railOpen.value||event.target.closest('.right-rail,button,a,input,select,textarea,[role=button]'))return;event.preventDefault();event.stopPropagation();railOpen.value=false;selectedUser.value=null;}
function openInbox(){page.value='map';menuOpen.value=false;selectedUser.value=null;activeChatUser.value=null;railTab.value='chat';railOpen.value=true;modal.value=''}
async function openChat(user){if(!verified.value){modal.value='私信互动';return}page.value='map';menuOpen.value=false;selectedUser.value=user;activeChatUser.value=user;chatThreads.value[user.name]??={messages:[],unread:0};chatThreads.value[user.name].unread=0;railTab.value='chat';railOpen.value=true;modal.value='';if(backendReady.value&&user.id){try{const {messages}=await apiRequest(`/messages/${encodeURIComponent(user.id)}`);chatThreads.value[user.name].messages=messages;persistChats()}catch(error){flash(error.message)}}nextTick(scrollChatToBottom)}
function scrollChatToBottom(){if(chatScrollRef.value)chatScrollRef.value.scrollTop=chatScrollRef.value.scrollHeight}
const chatReplyTimers=[];
function simulatedReply(message,peer){if(/[?？]|什么|啥|意思|怎么|为什么|为啥/.test(message))return '我刚想问你要不要一起参加校园活动～你更想去跑步、自习还是看演出？';if(/在哪|哪里|位置|见面|碰面/.test(message))return `我现在在${peer.area}附近，我们可以在附近的地标碰面～`;if(/课|考试|作业|复习/.test(message))return '我最近也在忙课程，要不要去图书馆一起复习？';if(/跑|运动|球|散步/.test(message))return '我也喜欢运动，我们可以约在体育场或水景步道～';if(/活动|一起|组队|参加/.test(message))return `可以呀！我现在在${peer.area}附近，我们看看有没有合适的活动～`;return `收到～我最近常在${peer.area}附近，下次可以一起逛校园。`}
async function sendChat(){const text=chatDraft.value.trim(),peer=activeChatUser.value;if(!text||!peer)return;try{if(backendReady.value){if(!peer.id)throw new Error('这位演示同学暂未连接实时账号');const {message}=await apiRequest(`/messages/${encodeURIComponent(peer.id)}`,{method:'POST',body:JSON.stringify({text})});const thread=chatThreads.value[peer.name]??={messages:[],unread:0};if(!thread.messages.some(item=>item.id===message.id))thread.messages.push(message);chatDraft.value='';persistChats();nextTick(scrollChatToBottom);return}const thread=chatThreads.value[peer.name]??={messages:[],unread:0};thread.messages.push({id:`m-${Date.now()}-${Math.random()}`,from:'me',text,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),createdAt:Date.now()});chatDraft.value='';persistChats();nextTick(scrollChatToBottom);const timer=setTimeout(()=>{const replyThread=chatThreads.value[peer.name]??={messages:[],unread:0};replyThread.messages.push({id:`r-${Date.now()}-${Math.random()}`,from:'peer',text:simulatedReply(text,peer),time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),createdAt:Date.now(),simulated:true});if(activeChatUser.value?.name!==peer.name||railTab.value!=='chat'||!railOpen.value)replyThread.unread=(replyThread.unread||0)+1;persistChats();nextTick(scrollChatToBottom)},850);chatReplyTimers.push(timer)}catch(error){flash(error.message)}}
const avatarFilters={sunshine:'none',lagoon:'hue-rotate(155deg) saturate(.82)',mint:'hue-rotate(95deg) saturate(.7)',peach:'hue-rotate(325deg) saturate(.78)'};
function useAction(){if(indoorBuilding.value&&indoorBuilding.value===buildingToEnter.value?.name){if(selected.value.type==='study'){study();return}if(selected.value.type==='food'){me.value.energy=Math.min(100,me.value.energy+12);flash('在食堂吃饭，精力恢复 +12');return}flash(`你正在${indoorBuilding.value}内，可以查看建筑资料或走出建筑`);return}const distance=Math.hypot(me.value.x-selected.value.x,me.value.z-selected.value.z);if(distance>28){sendTo(selected.value.x,selected.value.z,selected.value.name);return}if(selected.value.type==='study'){study();return}if(selected.value.type==='sport'){joinActivity(activities.value.find(event=>event.type==='运动'));return}if(selected.value.type==='home'){me.value.energy=Math.min(100,me.value.energy+18);flash('休息了一会儿，精力恢复 +18');return}if(selected.value.type==='food'){me.value.energy=Math.min(100,me.value.energy+12);flash('和同学一起吃了顿饭，精力恢复 +12');return}if(selected.value.type==='place'){flash(`已到达「${selected.value.name}」，可以查看周边地点`);return}flash('已到达这个地点，逛逛周围看看吧')}
function keyMove(e){if(modal.value&&e.key==='Tab'){const items=[...document.querySelectorAll('.modal-card button:not(:disabled),.modal-card input:not(:disabled),.modal-card textarea:not(:disabled),.modal-card select:not(:disabled),.modal-card [tabindex]:not([tabindex="-1"])')].filter(item=>item.offsetParent!==null);if(items.length){const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(e.key==='Escape'){if(modal.value){modal.value='';return}if(guideStep.value>=0){dismissGuide();return}if(railOpen.value){railOpen.value=false;return}if(invitation.value&&!currentActivity.value&&!playerMoving.value&&!enteringBuilding.value&&page.value==='map'){respondToInvitation(false);return}if(indoorBuilding.value){leaveInterior();return}if(controlMode.value){leaveControl();return}if(page.value!=='map'){page.value='map';return}}}
function showBuildingDetails(building){campusSelection.value=building;active.value=building.name;selectedUser.value=null;railTab.value='place';railOpen.value=true}
function receiveCampus(building){const shouldEnter=controlMode.value&&building.name!==indoorBuilding.value&&!['gate','field','stadium'].includes(building.kind);if(shouldEnter){campusSelection.value=building;active.value=building.name;selectedUser.value=null;railTab.value='place';railOpen.value=false;nextTick(()=>goInside(building,false));return}showBuildingDetails(building)}
function receiveFallbackCampus(building){campusSelection.value=building;active.value=building.name;selectedUser.value=null;railTab.value='place';railOpen.value=true;if(controlMode.value)flash('当前使用简化地点目录：可以查看建筑资料，角色移动和进楼需恢复三维地图')}
function locateUser(user){modal.value='';page.value='map';selectedUser.value=null;railTab.value='place';railOpen.value=true;campusSelection.value={name:user.area,description:`${user.name}目前${user.status}。点击头像可以查看同学资料。`,x:user.x,z:user.z};active.value=user.area;gameMap.value?.focus(user.x,user.z);flash(`已定位到${user.name}附近`)}
function inviteProfileUser(user){if(user.socialState==='low'){flash(`${user.name}当前处于消沉状态，暂不接收邀请`);return}modal.value='';flash(`已向${user.name}发出活动邀请（本地演示）`)}
function openProfile(){profileMoodDraft.value=me.value.socialState;modal.value='profile'}
function setSocialState(state){profileMoodDraft.value=state;if(state==='low')flash('保存后将暂停接收系统活动和同学邀约');else flash('保存后将恢复接收活动邀请')}
async function saveProfile(){me.value={...me.value,socialState:profileMoodDraft.value};persistProfile();if(me.value.socialState==='low')invitation.value=null;try{if(backendReady.value&&verified.value){const {user}=await apiRequest('/profile',{method:'POST',body:JSON.stringify({name:me.value.name,avatarTone:me.value.avatarTone,faculty:me.value.faculty,year:me.value.year,bio:me.value.bio,interests:me.value.interests,socialState:me.value.socialState,visibility:me.value.visibility})});backendUserId.value=user.id;attachCommunityEvents()}modal.value='';flash(backendReady.value?'个人资料已保存到本地后端':'个人资料已保存在本机')}catch(error){flash(error.message)}}
function canOfferInvite(force=false){return me.value.socialState==='active'&&!invitation.value&&!modal.value&&!currentActivity.value&&!activityRecap.value&&(force||!(guideStep.value>=0||controlMode.value||page.value!=='map'||playerMoving.value||enteringBuilding.value||railOpen.value))}
function offerActivityInvite(force=false){if(!canOfferInvite(force))return false;const available=users.value.filter(user=>user.socialState==='active'),event=activities.value[0];invitation.value={...event,source:'系统活动',inviter:'校园活动助手',invitedCount:available.length};invitationExpanded.value=false;return true}
function offerStudentInvite(force=false){if(!canOfferInvite(force))return false;const candidates=activities.value.filter(event=>event.organizer&&event.organizer!=='校园活动助手'&&event.joined<event.cap&&users.value.some(user=>user.name===event.organizer&&user.socialState==='active'));if(!candidates.length)return false;const event=candidates[Math.floor(Math.random()*candidates.length)],host=users.value.find(user=>user.name===event.organizer);if(!host)return false;const nearby=users.value.filter(user=>user.name!==host.name&&user.socialState==='active').length;invitation.value={...event,source:'同学邀请',inviter:host.name,invitedCount:nearby};invitationExpanded.value=false;return true}
function previewSystemInvite(){page.value='map';leaveControl();railOpen.value=false;menuOpen.value=false;offerActivityInvite(true);if(!invitation.value)flash(me.value.socialState==='low'?'当前为消沉状态，已暂停活动邀请':'暂时无法显示邀请，请先结束当前活动')}
function previewStudentInvite(){page.value='map';leaveControl();railOpen.value=false;menuOpen.value=false;offerStudentInvite(true);if(!invitation.value)flash(me.value.socialState==='low'?'当前为消沉状态，已暂停同学邀请':'暂无活跃同学发起活动，请稍后再试')}
function activityPeers(hostName=''){const peers=users.value.filter(user=>user.name!==hostName&&user.socialState==='active');for(let i=peers.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[peers[i],peers[j]]=[peers[j],peers[i]]}return peers.slice(0,2).map(user=>user.name)}
function joinActivity(event){if(!event)return;if(!verified.value){modal.value='报名活动';return}if(currentActivity.value?.title===event.title){page.value='map';controlMode.value=true;return}if(!event.joinedByMe){event.joinedByMe=true;event.joined=Math.min(event.cap,event.joined+1)}currentActivity.value={title:event.title,place:event.place,meta:event.meta,x:event.x,z:event.z,status:'正在前往集合点',description:event.description,source:event.organizer==='校园活动助手'?'系统活动':'同学邀请',hostName:event.organizer==='校园活动助手'?'':event.organizer,participants:activityPeers(event.organizer)};page.value='map';campusSelection.value={name:event.place,description:event.description,x:event.x,z:event.z};active.value=event.place;railOpen.value=false;sendTo(event.x,event.z,`${event.place}活动集合点`);flash(`已加入「${event.title}」演示活动，正在前往集合点`)}
function respondToInvitation(join){const invite=invitation.value;if(!invite)return;invitation.value=null;invitationExpanded.value=false;if(!join){flash('已跳过本次活动邀请，不会影响游戏状态');return}const listed=activities.value.find(event=>event.title===invite.title)||invite;if(!listed.joinedByMe){listed.joinedByMe=true;listed.joined=Math.min(listed.cap,listed.joined+1)}currentActivity.value={title:invite.title,place:invite.place,meta:invite.meta,x:invite.x,z:invite.z,status:'正在前往集合点',description:invite.description,source:invite.source,hostName:invite.source==='同学邀请'?invite.inviter:'',participants:activityPeers(invite.source==='同学邀请'?invite.inviter:'')};campusSelection.value={name:invite.place,description:invite.description,x:invite.x,z:invite.z};active.value=invite.place;page.value='map';sendTo(invite.x,invite.z,`${invite.place}活动集合点`);railOpen.value=false;flash(`已接受「${invite.title}」，奶龙正在步行前往集合点`)}
function startCurrentActivity(){if(!currentActivity.value||currentActivity.value.status!=='已到达集合点')return;currentActivity.value.status='活动进行中';currentActivity.value.endsAt=Date.now()+20000;currentActivity.value.remaining=20;clearInterval(activityTimer);activityTimer=setInterval(()=>{if(!currentActivity.value){clearInterval(activityTimer);return}currentActivity.value.remaining=Math.max(0,Math.ceil((currentActivity.value.endsAt-Date.now())/1000));if(currentActivity.value.remaining<=0){clearInterval(activityTimer);const finished={...currentActivity.value,attendees:[currentActivity.value.hostName,...currentActivity.value.participants].filter(Boolean)};currentActivity.value=null;activityRecap.value=finished;flash(`「${finished.title}」协作体验已完成，默契值 +1（原型）`)}},250);flash('活动开始，和附近的演示同学一起完成 20 秒协作体验')}
function openRecapHost(){const host=users.value.find(user=>user.name===activityRecap.value?.hostName);if(!host){flash('活动发起同学资料暂不可用');return}activityRecap.value=null;contact(host)}
function clearActivity(){clearInterval(activityTimer);currentActivity.value=null;flash('已退出当前活动，个人课程状态不受影响')}
let firstInvitationTimer,invitationInterval,firstStudentInviteTimer,studentInviteInterval;
onMounted(()=>{window.addEventListener('keydown',keyMove);initializeBackend();firstInvitationTimer=setTimeout(()=>offerActivityInvite(),60000);invitationInterval=setInterval(()=>offerActivityInvite(),180000);firstStudentInviteTimer=setTimeout(()=>offerStudentInvite(),105000);studentInviteInterval=setInterval(()=>offerStudentInvite(),240000)});
onUnmounted(()=>{communityEvents?.close();window.removeEventListener('keydown',keyMove);clearTimeout(firstInvitationTimer);clearInterval(invitationInterval);clearTimeout(firstStudentInviteTimer);clearInterval(studentInviteInterval);clearInterval(examTimer);clearInterval(activityTimer);clearTimeout(toastTimer);chatReplyTimers.forEach(clearTimeout)});
</script>

<template>
 <div class="app-shell" @pointerdown.capture="closeRailOnBlank" :class="{'menu-open':menuOpen,'rail-open':railOpen,'drawer-open':page!=='map','role-control':controlMode&&page==='map'}">
  <button v-if="page!=='map'" class="drawer-scrim" aria-label="点击空白处返回地图" @click="page='map';menuOpen=false"></button>
  <button v-if="railOpen&&page==='map'" class="rail-scrim" aria-label="点击空白处收起地点信息" @click="railOpen=false;selectedUser=null"></button>
  <button v-if="menuOpen" class="menu-scrim" aria-label="点击关闭校园菜单" @click="menuOpen=false"></button>
  <aside class="sidebar">
   <button v-if="menuOpen" class="sidebar-close" aria-label="关闭校园菜单" @click="menuOpen=false">×</button>
   <a class="brand" href="#" @click.prevent="navigate('map')"><span class="brand-mark"><img src="/nailong-avatar.png" alt="" /></span><span><strong>奶龙同学</strong><small>河海校园 · 一起生活</small></span></a>
   <div class="campus-switch"><span class="campus-dot"></span><span><b>河海大学常州校区</b><small>金坛 · 长荡湖校址 · 原型演示</small></span><span class="chevron">⌄</span></div>
   <div class="nav-label">校园生活</div>
   <nav><button v-for="[id,label] in nav" :key="id" :class="['nav-item',{active:page===id}]" @click="navigate(id)"><span class="nav-icon"><svg v-if="id==='map'" viewBox="0 0 24 24"><path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15m6-12v15"/></svg><svg v-else-if="id==='classes'" viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h3m-3 3h7"/></svg><svg v-else-if="id==='grades'" viewBox="0 0 24 24"><path d="M4 20V9m6 11V4m6 16v-7m5 7V7"/></svg><svg v-else-if="id==='community'" viewBox="0 0 24 24"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H5l1.2-3.1A7.5 7.5 0 1 1 20 11.5Z"/><path d="M8 11h8M8 14h5"/></svg><svg v-else viewBox="0 0 24 24"><path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1"/><circle cx="12" cy="12" r="5"/></svg></span>{{label }}<span v-if="id==='events'" class="nav-count">2</span></button></nav>
   <div class="sidebar-bottom"><div class="demo-note" role="status" aria-live="polite"><span class="demo-dot"></span>{{backendReady?'本地后端已连接 · 演示账号':'本机演示模式 · 后端离线'}}</div><button class="profile-row" @click="openProfile"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[me.avatarTone]}" alt="我的奶龙头像"><span><b>{{me.name}}</b><small>{{me.faculty}} · {{me.year}}</small></span><span class="more">···</span></button></div>
  </aside>
  <main class="main-column">
   <header class="topbar"><button class="game-menu" aria-label="打开校园菜单" @click="menuOpen=!menuOpen"><i></i><i></i></button><a class="game-brand" href="#" @click.prevent="page='map'"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[me.avatarTone]}" alt=""><b>奶龙同学</b></a><div class="crumb">河海校园 <span>/</span> {{nav.find(n=>n[0]===page)?.[1]}}</div><div class="top-actions"><div class="virtual-clock"><span class="clock-dot"></span>虚拟周三 <b>09:20</b></div><button class="icon-button" title="通知" @click="flash('暂时没有新通知')"><svg viewBox="0 0 24 24"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><i></i></button><button class="icon-button message-button" title="消息" aria-label="打开消息" @click="openInbox"><svg viewBox="0 0 24 24"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H5l1.2-3.1A7.5 7.5 0 1 1 20 11.5Z"/><path d="M8 11h8M8 14h5"/></svg><b v-if="chatUnread" class="message-count">{{chatUnread>9?'9+':chatUnread}}</b></button><button class="verify-button" :class="{verified}" @click="verified?flash('当前使用本地演示账号'):modal='verify'">{{verified?'演示账号已登录':'演示账号登录'}}</button></div></header>
  <div class="game-background"><CampusScene ref="gameMap" :users="mapUsers" :player="me" :control-mode="controlMode" @place="receiveCampus" @place-fallback="receiveFallbackCampus" @user="contact" @role="onRoleEvent" /></div><div v-if="page==='map'" class="map-scene-title"><h1>河海校园</h1><span>金坛 · 长荡湖校址 · 3D 示意模型</span></div>
   <Transition name="invite"><aside v-if="invitation&&!modal&&!currentActivity&&!playerMoving&&!enteringBuilding&&!railOpen&&page==='map'" class="activity-invitation" role="region" aria-label="活动邀请" aria-live="polite"><div class="invitation-top"><span class="invitation-mark">✳</span><div><small>{{invitation.source==='系统活动'?'SYSTEM ACTIVITY · 系统推荐':'STUDENT INVITE · 同学邀请'}}</small><b>{{invitation.source==='系统活动'?'校园活动助手':invitation.inviter}} 邀请你</b></div><button class="invitation-close" aria-label="跳过邀请" @click="respondToInvitation(false)">×</button></div><h3>{{invitation.title}}</h3><p>{{invitation.meta}}</p><div class="invitation-place">⌖ {{invitation.place}} · 接受后奶龙步行前往集合点</div><button class="invitation-details-toggle" :aria-expanded="invitationExpanded" @click="invitationExpanded=!invitationExpanded">{{invitationExpanded?'收起活动说明':'查看活动说明'}}</button><div v-if="invitationExpanded" class="invitation-expanded"><p v-if="invitation.description">{{invitation.description}}</p><div v-if="invitation.source==='系统活动'" class="invitation-group">{{invitation.source==='系统活动'?'系统同时':'发起同学同时'}}邀请附近 {{invitation.invitedCount}} 位活跃演示同学。</div></div><div class="invitation-actions"><button class="outline-small" @click="respondToInvitation(false)">暂不参加</button><button class="primary-button" @click="respondToInvitation(true)">参加并前往 <span>→</span></button></div></aside></Transition>
   <aside v-if="activityRecap&&!modal" class="activity-recap" role="status"><div class="recap-mark">✓</div><div class="recap-copy"><small>INTERACTION COMPLETE · &#x4E92;&#x52A8;&#x5B8C;&#x6210;</small><b>{{activityRecap.title}}</b><span>&#x4E00;&#x8D77;&#x5B8C;&#x6210;&#x4E86;&#x8FD9;&#x6B21;&#x6D3B;&#x52A8; · &#x9ED8;&#x5951;&#x503C; +1&#xFF08;&#x539F;&#x578B;&#xFF09;</span><span v-if="activityRecap.attendees.length">&#x540C;&#x4F34;&#xFF1A;{{activityRecap.attendees.join('、')}}</span></div><button v-if="activityRecap.hostName" class="outline-small" @click="openRecapHost">&#x8BA4;&#x8BC6;&#x53D1;&#x8D77;&#x540C;&#x5B66;</button><button class="recap-close" aria-label="&#x5173;&#x95ED;&#x6D3B;&#x52A8;&#x603B;&#x7ED3;" @click="activityRecap=null">×</button></aside>
   <aside v-if="currentActivity||exam.status==='考试中'" class="activity-presence"><span class="presence-dot"></span><span><small>{{exam.status==='考试中'?'阶段测验进行中':currentActivity.status||'正在参加'}}</small><b>{{exam.status==='考试中'?exam.name:currentActivity.title}}</b></span><span v-if="exam.status==='考试中'" class="activity-countdown">{{exam.remaining}} 秒</span><template v-else><button v-if="currentActivity.status==='正在前往集合点'" @click="sendTo(currentActivity.x,currentActivity.z,`${currentActivity.place}活动集合点`)" aria-label="步行前往活动集合点">前往</button><button v-else-if="currentActivity.status==='已到达集合点'" class="activity-start" @click="startCurrentActivity">开始活动</button><span v-else-if="currentActivity.status==='活动进行中'" class="activity-countdown">{{currentActivity.remaining}} 秒</span><button @click="clearActivity" aria-label="退出当前活动">退出</button></template></aside>
   <div class="page-content">
    <button v-if="page!=='map'" class="drawer-close" @click="page='map'" aria-label="收起面板，返回校园地图">×<span>返回地图</span></button>
    <template v-if="page==='map'">
       <button v-if="!controlMode" class="overview-edge-button" aria-label="开始校园体验引导" title="开始校园体验引导" @click="startGuide"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="m15.5 8.5-2.2 4.8-4.8 2.2 2.2-4.8 4.8-2.2Z"/></svg><span>导览</span></button>
      <section v-if="currentGuideStep&&page==='map'" class="first-visit-guide" aria-live="polite" aria-label="首次体验引导"><div class="guide-progress"><i v-for="(_,index) in guideSteps" :key="index" :class="{done:index<guideStep,current:index===guideStep}"></i></div><div class="guide-copy"><small>校园初体验 · {{guideStep+1}} / {{guideSteps.length}}</small><b>{{currentGuideStep.title}}</b><p>{{currentGuideStep.body}}</p></div><div class="guide-actions"><button class="guide-skip" @click="dismissGuide">跳过</button><button class="primary-button" @click="advanceGuide">{{currentGuideStep.action}} <span>→</span></button></div></section>
     <section class="map-layout">
      <div class="map-panel"><div class="map-topline"><div><h1>河海校园</h1><span>金坛 · 长荡湖校址 · 3D 示意模型</span></div><div class="map-legend"><span><i class="legend-other"></i>演示同学</span><span><i class="legend-place"></i>地点</span></div></div>
       <div class="map-canvas">
        <svg class="campus-map" :viewBox="mapViewBox" role="img" aria-label="河海大学常州校区金坛长荡湖校址示意地图，非测绘图">
         <defs><pattern id="grass" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="3" cy="5" r="1" fill="#d9e3cf" opacity=".5"/><circle cx="15" cy="16" r="1.1" fill="#d9e3cf" opacity=".42"/></pattern><filter id="soft"><feGaussianBlur stdDeviation="3"/></filter></defs>
         <rect width="1000" height="606" fill="#e9eee5"/><polygon :points="points(campusBoundary)" fill="#f5f6ee" stroke="#dce4d9" stroke-width="2"/><polygon :points="points(campusBoundary)" fill="url(#grass)"/>
         <path d="M0 332 C180 318 234 327 323 315 C420 300 483 290 580 304 C683 320 754 296 1000 283 L1000 337 C785 350 707 371 585 349 C473 330 413 353 329 366 C213 385 166 364 0 382Z" fill="#d7e9e6"/><path d="M0 343 C190 327 251 343 322 328 C421 310 480 305 582 321 C698 340 766 311 1000 298" fill="none" stroke="#fff" stroke-width="3" opacity=".85"/>
         <polygon :points="points(lakeOutline)" fill="#b7d8d2" stroke="#9cc5bd" stroke-width="2"/>
         <polyline :points="points(centralRing)" fill="none" stroke="#dfd6c1" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/>
         <polyline v-for="(route,i) in roadRoutes.slice(1)" :key="'r'+i" :points="points(route.points)" fill="none" :stroke="i<3?'#d9d6ca':'#e5dfcf'" :stroke-width="Math.max(3,route.width/1400*1000)" stroke-linecap="round" stroke-linejoin="round"/>
         <polyline v-for="(path,i) in gardenPaths" :key="'p'+i" :points="points(path.points)" fill="none" stroke="#faf9f3" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>
         <g v-for="(b,i) in buildingsOnMap" :key="b.id" :transform="`translate(${b.px-b.pw/2} ${b.py-b.ph/2})`"><rect :width="b.pw" :height="b.ph" rx="b.kind==='dorm'?2:4" :fill="b.category==='教学科研'?'#d8dfd0':b.category==='文体空间'?'#ead9cc':'#e6dfce'" stroke="#c7cbbb" stroke-width="1.3"/><rect x="2" y="2" :width="Math.max(2,b.pw-4)" height="2" rx="1" fill="#fff" opacity=".65"/><text v-if="['01','02','10','19','54','31'].includes(b.id)" :x="b.pw/2" :y="b.ph/2+2" text-anchor="middle" font-size="7" fill="#667263">{{b.name.replace('学生宿舍 · ','')}}</text></g>
         <g v-for="spot in spots" :key="spot.name" class="map-spot" :transform="`translate(${zone(spot).split(',').join(' ')})`" @click="selectSpot(spot)"><circle r="11" fill="#fff" stroke="#78967f" stroke-width="1.4"/><circle r="3.5" fill="#638b73"/><text y="24" text-anchor="middle">{{spot.name}}</text></g>
         <g v-for="u in mapUsers" :key="u.name" class="map-user" role="button" tabindex="0" :aria-label="`查看${u.name}的资料`" :transform="`translate(${mapX(u.x)} ${mapY(u.z)})`" @click="contact(u)" @keydown.enter="contact(u)"><circle r="20" fill="#fff" stroke="#fff" stroke-width="2"/><circle r="17" :fill="u.color" opacity=".3"/><image href="/nailong-avatar.png" :style="{filter:avatarFilters[u.avatarTone]}" x="-15" y="-18" width="30" height="34" preserveAspectRatio="xMidYMid meet"/><rect x="-34" y="21" width="68" height="16" rx="8" fill="#fff" stroke="#e5e9e2" stroke-width=".8"/><text y="32" text-anchor="middle">{{u.name}}</text><title>{{u.name}} · {{u.status}}</title></g>
         <text x="495" y="594" class="map-watermark">河海大学常州校区 · 金坛校址示意（位置与尺度为近似）</text>
        </svg>
        <div class="map-compass">N <span>↑</span></div>
         <button class="nearby-toggle" @click="railOpen=!railOpen">{{railOpen?'收起信息':'校园信息 · 地点与同学'}}</button>
       </div>
        <div class="map-footer"><span><i class="demo-dot"></i>地图上 <b>{{mapUsers.length}}</b> 位演示同学 <em>·</em> 点击头像查看资料 <em>·</em> 当前地点：{{selected.place}}</span><span class="map-hint">官方资料校核至 2026-11 · 建筑/道路坐标为近似示意</span></div>
      </div>
      <aside class="right-rail" :class="{'chat-inbox-open':railTab==='chat'&&!activeChatUser}" :aria-label="railTab==='place'?'地点详情':railTab==='nearby'?'同学信息':railTab==='chat'?'消息': '我的奶龙'">
       <div class="rail-topbar"><div><small>{{railTab==='chat'?'消息中心':'校园信息'}}</small><b>{{railTab==='place'?(buildingToEnter?.name||selected.name):railTab==='nearby'?(selectedUser?.name||'附近同学'):railTab==='chat'?(activeChatUser?.name||'最近对话'):'我的奶龙'}}</b></div><button class="rail-close" aria-label="关闭信息面板" @click="railOpen=false">×</button></div>
       <nav class="rail-tabs" aria-label="信息面板切换"><button :class="{active:railTab==='place'}" @click="selectedUser=null;railTab='place'">地点</button><button :class="{active:railTab==='nearby'}" @click="showNearby()">同学 <span>{{visibleUsers.length}}</span></button><button :class="{active:railTab==='chat'}" @click="railTab='chat';activeChatUser=null">消息 <span v-if="chatUnread">{{chatUnread>9?'9+':chatUnread}}</span></button><button :class="{active:railTab==='mine'}" @click="railTab='mine'">我的</button></nav>
       <article v-if="railTab==='chat'" class="chat-panel">
        <template v-if="!activeChatUser">
         <div class="chat-inbox-heading"><div><b>找同学聊聊</b><small>选择一位同学开始对话</small></div><span>{{users.length}} 位同学</span></div>
         <div class="chat-demo-note">{{backendReady?'本地后端私信 · 双方在线时实时同步':'原型演示对话 · 消息仅保存在此浏览器'}}</div>
         <div class="chat-list-tools"><label class="chat-search"><span aria-hidden="true">⌕</span><input v-model="chatQuery" type="search" aria-label="搜索同学或最近消息" placeholder="搜索同学或最近消息"><button v-if="chatQuery" type="button" aria-label="清除搜索" @click="chatQuery=''">×</button></label><label class="chat-sort-label">排序<select v-model="chatSort" aria-label="消息列表排序"><option value="recent">最近联系</option><option value="unread">未读优先</option></select></label></div>
         <p class="chat-result-count" aria-live="polite">{{chatList.length}} 位同学{{chatQuery?'符合搜索':''}}</p>
         <button v-for="item in chatList" :key="item.user.name" class="chat-thread-row" @click="openChat(item.user)">
          <span class="chat-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[item.user.avatarTone]}" alt=""></span>
          <span class="chat-thread-copy"><b>{{item.user.name}}<i :class="['chat-state-dot',item.user.socialState]"></i></b><small>{{item.thread.messages?.at(-1)?.text||'点击发送第一条消息'}}</small></span>
          <span class="chat-thread-meta"><small>{{item.thread.messages?.at(-1)?.time||''}}</small><i v-if="item.thread.unread" class="chat-unread">{{item.thread.unread>9?'9+':item.thread.unread}}</i></span>
         </button>
         <div v-if="!chatList.length" class="chat-search-empty">没有找到匹配的同学或消息。试试昵称关键词，或清空搜索。</div>
        </template>
        <template v-else>
         <div class="chat-room-head"><button class="chat-back" aria-label="返回消息列表" @click="activeChatUser=null">‹</button><span class="chat-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[activeChatUser.avatarTone]}" alt=""></span><div><b>{{activeChatUser.name}}</b><small>{{activeChatUser.area}} · {{activeChatUser.socialState==='active'?'活跃':'暂时休息'}}</small></div></div>
         <div class="chat-demo-note">{{backendReady?'本地后端私信 · 演示账号之间实时同步':'本机演示对话 · 消息仅保存在此浏览器'}}</div>
         <div ref="chatScrollRef" class="chat-messages" aria-live="polite">
          <div v-if="!activeMessages.length" class="chat-empty"><span class="chat-empty-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[activeChatUser.avatarTone]}" alt=""></span><b>和 {{activeChatUser.name}} 打个招呼</b><p>聊聊校园生活、课程或一起参加的活动。</p></div>
          <div v-for="message in activeMessages" :key="message.id" :class="['chat-message',message.from==='me'?'mine':'theirs']"><div class="chat-bubble"><small v-if="message.simulated" class="simulated-tag">模拟回复</small>{{message.text}}</div><time>{{message.time}}</time></div>
         </div>
         <form class="chat-composer" @submit.prevent="sendChat"><textarea v-model="chatDraft" rows="1" maxlength="300" aria-label="输入消息" placeholder="写一条消息…" @keydown.enter.exact.prevent="sendChat"></textarea><button type="submit" :disabled="!chatDraft.trim()" aria-label="发送消息">发送</button></form>
        </template>
       </article>
       <article v-if="railTab==='mine'" class="character-card"><div class="character-art"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[me.avatarTone]}" alt="奶龙角色"/><span class="character-status"><i></i>{{me.socialState==='active'?'活跃 · 接收邀请':'消沉 · 暂不接收'}}</span><span class="small-spark">✳</span></div><div class="character-info"><span class="tiny-label">MY NAILONG</span><h2>{{me.name}}</h2><div class="meter-label"><span>今日精力</span><b>{{me.energy}}%</b></div><div class="meter"><i :style="{width:me.energy+'%'}"></i></div><button class="text-link" @click="openProfile">编辑个人资料与奶龙 <span>→</span></button></div></article>
       <article v-if="railTab==='place'" class="location-card"><div class="rail-heading"><span class="place-icon">⌖</span><div><small>{{indoorBuilding===buildingToEnter?.name?'当前所在建筑':'当前地点'}}</small><b>{{buildingToEnter?.name||selected.name}}</b></div><span class="open-pill">{{indoorBuilding===buildingToEnter?.name?'楼内':selected.time}}</span></div>
        <div v-if="buildingInfo" class="building-photos"><figure v-for="photo in buildingInfo.photos" :key="photo.src"><img :src="photo.src" :alt="photo.caption" loading="lazy"><figcaption>{{photo.caption}}</figcaption></figure></div>
        <p v-if="buildingInfo" class="building-facts">{{buildingInfo.facts}}</p><p v-else>{{selected.desc}}</p><div v-if="buildingInfo?.visual" class="building-note">{{buildingInfo.visual}}</div><div v-if="buildingInfo?.usage" class="building-note">{{buildingInfo.usage}}</div>
        <div class="location-meta"><span>⌖ {{selected.place}}</span><span v-if="buildingInfo">资料状态 · 参考整理</span><span v-else>◷ 约 3 分钟</span></div>
        <div v-if="indoorBuilding===buildingToEnter?.name" class="building-status-panel"><div class="building-status-head"><span>楼内演示状态</span><b>原型空间</b></div><small>不代表真实开放或门禁状态 · 当前在楼内 {{insideUsers.length+1}} 位模拟角色</small><div class="inside-user-row me-inside"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[me.avatarTone]}" alt=""><span><b>{{me.name}}</b><small>你 · 正在建筑内</small></span><i>我</i></div><button v-for="user in insideUsers" :key="user.name" class="inside-user-row" @click="contact(user)"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[user.avatarTone]}" alt=""><span><b>{{user.name}}</b><small>{{user.status}}</small></span><i>查看</i></button></div>
        <button class="primary-button" @click="useAction">{{indoorBuilding===buildingToEnter?.name?'在楼内 · 进行地点互动':selected.type==='study'?'去自习 · 提升备考度':selected.type==='sport'?'找同学一起跑步':selected.type==='home'?'回寝休息':selected.type==='food'?'去吃饭 · 恢复精力':'前往这个地点'}}<span>→</span></button><button v-if="buildingInfo" class="interior-button" @click="indoorBuilding===buildingToEnter?.name?leaveInterior():goInside(buildingToEnter)"><span>{{indoorBuilding===buildingToEnter?.name?'↙':'↗'}}</span> {{indoorBuilding===buildingToEnter?.name?'走出建筑 · 返回入口外':'步行到入口 · 查看楼内状态'}}</button></article>
       <article v-if="railTab==='nearby'&&selectedUser" class="user-detail-card"><button class="back-to-friends" @click="selectedUser=null">← 返回附近同学</button><div class="user-detail-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[selectedUser.avatarTone]}" alt="奶龙头像"></div><span class="tiny-label">演示用户资料</span><h2>{{selectedUser.name}}</h2><p>{{selectedUser.faculty}} · {{selectedUser.year}}</p><blockquote>{{selectedUser.bio}}</blockquote><div class="user-detail-row"><b>兴趣</b><span>{{selectedUser.interests}}</span></div><div class="user-detail-row"><b>目前</b><span>{{selectedUser.status}} · {{selectedUser.area}}</span></div><div class="user-detail-row"><b>社交状态</b><span :class="['profile-mood',selectedUser.socialState]">{{selectedUser.socialState==='low'?'消沉 · 暂不接收邀请':'活跃 · 可接收邀请'}}</span></div><button class="primary-button message-user-button" @click="openChat(selectedUser)">发送消息</button><div class="profile-actions"><button class="outline-small" @click="locateUser(selectedUser)">定位同学</button><button class="outline-small" :disabled="selectedUser.socialState==='low'" @click="inviteProfileUser(selectedUser)">{{selectedUser.socialState==='low'?'暂不接收邀约':'邀请参加活动'}}</button></div><button class="text-link public-greet" @click="flash(`已向${selectedUser.name}打招呼`)">打个招呼 <span>→</span></button></article>
       <article v-else-if="railTab==='nearby'" class="friends-card"><div class="section-mini-head"><b>附近同学 <small>{{visibleUsers.length}} / {{users.length}}</small></b><button @click="page='events';railOpen=false">活动广场 →</button></div><div class="user-filters"><label><span class="sr-only">按区域筛选同学</span><select v-model="userFilter"><option>全部区域</option><option>中心水景</option><option>东侧教学区</option><option>西侧生活区</option><option>体育场</option><option>东侧生活区</option></select></label><label><span class="sr-only">按社交状态筛选同学</span><select v-model="moodFilter"><option>全部状态</option><option value="active">活跃</option><option value="low">消沉</option></select></label></div><button v-for="u in visibleUsers" :key="u.name" class="friend-row" @click="contact(u)"><span class="friend-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[u.avatarTone]}" alt=""></span><span class="friend-text"><b>{{u.name}}</b><small>{{u.status}} · {{u.area}}</small></span><span class="social-state" :class="u.socialState">{{u.socialState==='low'?'暂不接收':'活跃'}}</span></button><div v-if="!visibleUsers.length" class="nearby-empty">这个筛选下暂时没有同学，试试其他区域或状态。</div></article>
      </aside>
     </section>
     <nav class="game-dock" aria-label="校园功能"><div v-if="page==='map'" class="mode-edge-rail" aria-label="地图视角与奶龙操控">
    <button class="mode-edge-button" :class="{active:controlMode}" :aria-label="controlMode?'返回校园总览':'操控我的奶龙'" :title="controlMode?'返回校园总览':'操控我的奶龙'" @click="controlMode?leaveControl():enterControl()">
     <span class="mode-edge-avatar"><span class="mode-edge-avatar-image"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[me.avatarTone]}" alt=""></span><svg viewBox="0 0 24 24" aria-hidden="true"><path v-if="controlMode" d="M12 5v14m0 0-6-6m6 6 6-6"/><path v-else d="M12 19V5m0 0 6 6m-6-6-6 6"/></svg></span>
     <span class="mode-edge-label">{{controlMode?'总览':'操控'}}</span>
    </button>
    <button v-if="controlMode&&indoorBuilding" class="mode-edge-action" aria-label="走出当前建筑" title="走出当前建筑" @click="leaveInterior"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m0 0-6-6m6 6-6 6"/></svg></button>
    <button v-else-if="controlMode&&(playerMoving||enteringBuilding)" class="mode-edge-action" aria-label="停止移动" title="停止移动" @click="gameMap?.stopPlayer()"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="6" y="6" width="12" height="12" rx="2"/></svg></button>
    <button v-if="controlMode" class="mode-edge-action" :aria-expanded="helpOpen" aria-label="操控说明" title="操控说明" @click="helpOpen=!helpOpen"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M9.7 9a2.4 2.4 0 1 1 4.2 1.6c-1.2 1.1-1.9 1.4-1.9 3m0 3h.01"/></svg></button>
    <aside v-if="controlMode&&helpOpen" class="mode-edge-help" aria-label="奶龙操控说明"><b>操控奶龙</b><span>左键地面：步行前往</span><span>左键建筑：走到入口并进入</span><span>WASD：微操奶龙走位 · 右键拖动：移动视野</span><button @click="helpOpen=false">知道了</button></aside>
   </div>
      <template v-if="!controlMode"><button @click="page='classes'">课表</button><button @click="page='grades'">成绩</button><button @click="page='community';communityTab='feed'">社区</button><button @click="page='events'">活动</button><button @click="railOpen=!railOpen">附近</button></template></nav>
     <section class="bottom-grid"><article class="today-card"><div class="section-title"><div><span class="section-kicker">虚拟日程 · 周三</span><h3>接下来的一节课</h3></div><button class="text-link" @click="page='classes'">完整课表 →</button></div><div class="next-class"><div class="class-time"><b>09:50</b><span>还有 30 分钟</span></div><div class="class-line"></div><div class="class-detail"><b>大学英语（交流课）</b><span>公共教学楼 · 演示教室 B</span></div><button class="outline-small" @click="page='classes'">查看</button></div></article><article class="exam-card"><div class="section-title"><div><span class="section-kicker">原型考试安排</span><h3>阶段测验</h3></div><span class="exam-icon">✳</span></div><div class="exam-row"><div><b>{{exam.name}}</b><span>{{exam.date}}</span></div><button v-if="!exam.score" class="outline-small" :disabled="exam.status==='考试中'" @click="sitExam">{{exam.status==='考试中'?`考试中 · ${exam.remaining}s`:exam.status==='待考'?'继续测验':'前往图书馆考试 →'}}</button><span v-else class="passed-tag">{{exam.score}} 分 · {{gradeStatus}}</span></div><div class="prep-line"><span>当前备考度 {{me.prep}}%</span><div><i :style="{width:me.prep+'%'}"></i></div><button @click="go(spots[0])">去图书馆</button></div></article></section>
    </template>
     <template v-else-if="page==='classes'"><section class="page-heading"><div><span class="section-kicker">虚拟日程 · 节次时间参考公开校历</span><h1>虚拟课表</h1><p>先走到教室，再开始上课；45 秒为玩法压缩时长。课程、教室、周次和出勤数据均为演示，不是学校教务安排。</p></div><div class="week-switch"><button>‹</button><b>虚拟第 2 周 · 周三</b><button>›</button></div></section><div class="schedule-layout"><section class="schedule-main"><div class="date-strip"><span>周一</span><span>周二</span><span class="today">周三<small>虚拟</small></span><span>周四</span><span>周五</span></div><article v-for="(c,i) in classes" :key="c.course" class="course-card"><div class="course-time">{{c.time}}<span>{{c.period}}</span></div><div class="course-marker" :class="'c'+i"></div><div class="course-info"><span class="course-type">{{i===2?'校园实践 · 原型':'课程示例 · 原型'}}</span><h3>{{c.course}}</h3><p>⌖ {{c.room}}</p><span :class="['attendance-state',{done:c.status==='已完成'}]">{{c.status==='上课中'?`上课中 · ${c.remaining} 秒`:c.status}}</span></div><button v-if="c.status!=='已完成'" class="primary-button compact" :disabled="c.status==='上课中'" @click="attend(c)">{{c.status==='已到教室'?'开始上课':c.status==='上课中'?'请专心听课':'前往教室 →'}}</button><span v-else class="completed-check">✓ 已签到</span></article><div class="schedule-note">时间节次示例取自河海大学公开校历所列作息（2023–2024学年版本）；实际课表、教室、课程、考试及出勤规则以当学期教务系统和校方通知为准。本页游戏成绩与缺勤惩罚均为原型机制。</div></section><aside class="grade-summary"><span class="section-kicker">原型进度记录</span><h3>本学期状态</h3><div class="grade-ring"><strong>{{grade}}</strong><span>虚拟综合分</span></div><div class="grade-line"><span>模拟出勤</span><b>{{me.att}}%</b></div><div class="grade-line"><span>模拟作业</span><b>{{me.assignment}}%</b></div><div class="grade-line"><span>图书馆备考度</span><b>{{me.prep}}%</b></div><button class="text-link" @click="page='grades'">查看成绩构成 →</button></aside></div></template>
    <template v-else-if="page==='grades'"><section class="page-heading"><div><span class="section-kicker">原型进度记录</span><h1>课程与成绩</h1><p>把每一次到课、练习和复习都算进自己的成长轨迹。</p></div><span class="demo-tag">虚构成绩 · 可交互</span></section><div class="grades-layout"><article class="score-main"><div class="score-top"><div><span class="section-kicker">虚拟课程示例</span><h2>水利工程导论</h2><p>虚拟学期第 2 周 · 原型学分 3</p></div><div class="score-number">{{grade}}<small>/100</small></div></div><div class="score-status"><span>原型课程状态</span><b :class="gradeStatus==='需要补考'?'fail':''">{{gradeStatus}}</b></div><div class="score-parts"><div><span>模拟出勤 <small>30%</small></span><div><i :style="{width:me.att+'%'}"></i></div><b>{{me.att}}</b></div><div><span>模拟作业 <small>20%</small></span><div><i :style="{width:me.assignment+'%'}"></i></div><b>{{me.assignment}}</b></div><div><span>模拟考试 <small>50%</small></span><div><i :style="{width:me.final+'%'}"></i></div><b>{{me.final||'—'}}</b></div></div><div class="formula-note">权重、及格线、缺勤扣分和补考条件仅为游戏玩法设定，不代表河海大学课程考核政策。图书馆互动只改变原型内的备考值。</div><button class="primary-button" @click="page='classes'">回课表完成学习 <span>→</span></button></article><aside class="growth-card"><span class="section-kicker">YOUR PROGRESS</span><h3>一点一滴，都是进步</h3><img src="/nailong-avatar.png" alt="奶龙正在学习"><p>今天在图书馆学习一次，备考度就提升了一截。坚持下去，考试时会更有把握。</p><button class="outline-small" @click="go(spots[0]);page='map'">去图书馆学习</button></aside></div><section class="exam-history"><h3>原型考试日历</h3><div class="exam-calendar"><span class="calendar-day">虚拟第 3 周</span><b>{{exam.name}}</b><span>{{exam.date}}</span><button class="text-link" @click="sitExam">{{exam.score?'查看考试结果':exam.status==='考试中'?`测验进行中 · ${exam.remaining}s`:'前往图书馆参加测验 →'}}</button></div></section></template>
    <template v-else-if="page==='community'">
     <section class="community-page">
      <header class="community-heading"><div><span class="section-kicker">CAMPUS COMMUNITY · 演示空间</span><h1>校园社区</h1><p>分享校园生活、交换实用消息，也可以发现同学发布的闲置物品。</p></div><span class="community-demo-badge">{{backendReady?'本地后端已连接':'后端离线 · 本机演示'}} · 非官方内容</span></header>
      <nav class="community-tabs" aria-label="社区内容"><button :class="{selected:communityTab==='feed'}" @click="communityTab='feed'">校园动态 <span>{{communityPosts.length}}</span></button><button :class="{selected:communityTab==='market'}" @click="communityTab='market'">闲置集市 <span>{{listings.length}}</span></button></nav>
      <template v-if="communityTab==='feed'">
       <section class="community-composer"><div class="community-my-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[me.avatarTone]}" alt="我的奶龙头像"></div><div class="community-compose-main"><textarea v-model="communityDraft" maxlength="300" rows="2" aria-label="发布校园动态" placeholder="分享一条校园里的新鲜事…"></textarea><div class="community-compose-actions"><label>发布为 <select v-model="communityDraftType"><option>生活分享</option><option>校园消息</option><option>学习搭子</option><option>失物招领</option><option>活动招募</option></select></label><button class="primary-button compact" :disabled="!communityDraft.trim()||postingCommunity" @click="publishCommunityPost">{{postingCommunity?'正在发布…':'发布动态'}} <span>→</span></button></div><small>访客可浏览；发布、点赞和评论需登录演示账号。真实校内认证尚未接入。</small></div></section>
       <div class="community-feed-tools"><div><b>大家在聊</b><small>校园消息由同学分享，不代表校方公告</small></div><div class="community-filters"><button v-for="filter in ['全部','校园消息','生活分享','学习搭子','活动招募','失物招领']" :key="filter" :class="{selected:communityFilter===filter}" @click="communityFilter=filter">{{filter}}</button></div></div>
       <div class="community-feed"><article v-for="post in filteredCommunityPosts" :key="post.id" class="community-post"><header class="community-post-head"><span class="community-post-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[post.tone]||avatarFilters.sunshine}" alt=""></span><div><b>{{post.author}}</b><small>{{post.time}} · 演示同学</small></div><span class="community-post-type">{{post.type}}</span></header><p class="community-post-text">{{post.text}}</p><div class="community-post-actions"><button :class="{liked:post.liked}" @click="toggleCommunityLike(post)"><span>{{post.liked?'♥':'♡'}}</span> {{post.likes}} 赞</button><span>💬 {{post.comments.length}} 条评论</span><button class="community-share-action" @click="quoteCommunityPost(post)">引用分享</button></div><div v-if="post.comments.length" class="community-comments"><p v-for="(comment,index) in post.comments" :key="index"><b>{{comment.author}}</b><span>{{comment.text}}</span></p></div><form class="community-comment-form" @submit.prevent="addCommunityComment(post)"><input v-model="commentDrafts[post.id]" maxlength="120" :aria-label="`回复${post.author}`" placeholder="友好地聊两句…"><button type="submit" :disabled="!(commentDrafts[post.id]||'').trim()">评论</button></form></article><div v-if="!filteredCommunityPosts.length" class="community-empty">这个分类还没有动态，来发布第一条分享吧。</div></div>
      </template>
      <template v-else>
       <div class="community-market-intro"><span>♧</span><div><b>校园闲置交换</b><small>先沟通议价，再约公共地点当面核验与交接；原型不含线上付款。</small></div><button class="primary-button compact" @click="openListingForm">＋ 发布闲置</button></div>
       <div class="market-tools"><div class="search-box"><span>⌕</span><input v-model="marketQuery" placeholder="找教材、生活用品或运动装备"></div><div class="filter-pills"><button v-for="filter in ['全部','教材资料','生活好物','运动户外']" :key="filter" :class="{chosen:marketFilter===filter}" @click="marketFilter=filter">{{filter}}</button></div></div><div class="market-grid"><article v-for="item in filteredListings" :key="item.title" class="listing-card"><div class="listing-image" :style="{background:item.color}"><span>{{item.tag}}</span><div class="listing-illustration">{{item.tag==='学习用品'?'尺':'书'}}</div><i>演示商品</i></div><div class="listing-info"><h3>{{item.title}}</h3><div class="listing-price">{{item.price}} <small>可友好议价</small></div><div class="seller-line"><span class="seller-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[item.sellerTone]||'none'}" alt=""></span><span>{{item.seller}}<small>{{item.place}}</small></span><button @click="contactSeller(item)">联系</button></div></div></article><div v-if="!filteredListings.length" class="community-empty">暂时没有符合条件的闲置物品。</div></div><div class="market-footnote">请在公共场所当面核验物品并交接；不要在原型中填写真实联系方式或支付信息。</div>
      </template>
     </section>
    </template>
    <template v-else><section class="page-heading"><div><span class="section-kicker">MEET & MAKE THINGS</span><h1>活动广场</h1><p>系统会根据你的状态推荐活动；时间、地点、报名人数和邀请均为本机原型模拟。</p></div><div class="event-preview-actions"><button class="outline-small" @click="previewStudentInvite">&#x9884;&#x89C8;&#x540C;&#x5B66;&#x53D1;&#x8D77;</button><button class="primary-button" @click="previewSystemInvite">预览系统邀请</button></div></section><div class="system-event-guide"><span class="guide-spark">✳</span><div><b>校园活动助手</b><p>系统活动是主要邀约来源；活跃状态可接收活动和同学邀请。消沉状态会暂停所有邀约。</p></div><button class="outline-small" @click="openProfile">管理状态</button></div><div class="event-banner"><div><span class="section-kicker">原型活动时间安排</span><h2>在现实之外，<br>也可以一起做点什么。</h2><p>当前是原型演示活动，报名与角色均为本地模拟。</p><button @click="previewSystemInvite">在地图上预览活动邀请 →</button></div><div class="banner-art"><span class="orbit o1"></span><span class="orbit o2"></span><img src="/nailong-avatar.png" alt="奶龙"><span class="banner-note">一起玩吧</span></div></div><div class="event-list"><div class="section-title"><div><span class="section-kicker">OPEN INVITATIONS</span><h3>正在找队友</h3></div><div class="filter-pills"><button v-for="filter in ['全部活动','运动','组队课题','校园演出']" :key="filter" :class="{chosen:activityFilter===filter}" @click="activityFilter=filter">{{filter}}</button></div></div><article v-for="e in filteredActivities" :key="e.title" class="event-row"><div class="event-type">{{e.type==='运动'?'运动搭子':e.type}}</div><div class="event-main"><h3>{{e.title}}</h3><p>{{e.meta}}</p><div class="event-attendees"><span v-for="n in Math.min(e.joined,4)" :key="n" class="mini-attendee"><img src="/nailong-avatar.png" alt=""></span><span>{{e.joined}} 位奶龙已报名 · {{e.cap}} 人上限</span><span class="event-organizer">&#x53D1;&#x8D77;&#x4EBA;&#xFF1A;{{e.organizer||'&#x6821;&#x56ED;&#x6D3B;&#x52A8;&#x52A9;&#x624B;'}}</span></div></div><div class="event-progress"><div><i :style="{width:e.joined/e.cap*100+'%'}"></i></div><span>{{e.joined}} / {{e.cap}}</span></div><button class="outline-small" :class="{'event-joined':e.joinedByMe}" :disabled="e.joined>=e.cap&&!e.joinedByMe" @click="joinActivity(e)">{{e.joinedByMe?'已加入 · 查看地图 →':e.joined>=e.cap?'名额已满':'加入活动 →'}}</button></article></div></template>
   </div>
  </main>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=''"><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button ref="modalCloseButton" class="modal-close" aria-label="关闭对话框" @click="modal=''">×</button><template v-if="modal==='verify'||['发布闲置','联系卖家','发起活动','报名活动','组队跑步','发布社区动态','点赞互动','评论互动','分享动态','私信互动'].includes(modal)"><span class="modal-icon">✳</span><span class="section-kicker">CAMPUS MEMBER ACCESS</span><h2 id="modal-title">{{modal==='verify'?'创建演示账号':`需要先登录演示账号才能${modal}`}}</h2><p>此账号仅用于体验本地后端，不代表已验证河海大学校内身份。不会收集学号、密码或真实身份信息。</p><div class="demo-identity"><span>🎓</span><div><b>河海大学 · 演示同学</b><small>仅用于本地功能演示</small></div><span class="verified-badge">DEMO</span></div><button class="primary-button full" @click="verify">创建演示账号并继续 <span>→</span></button><button class="text-link modal-cancel" @click="modal=''">先逛逛再说</button></template><template v-else-if="modal==='listing-create'"><div class="profile-editor listing-editor"><span class="section-kicker">CAMPUS FLEA MARKET</span><h2 id="modal-title">发布闲置物品</h2><p>请仅填写商品和公共交接地点，不要放入电话、学号或其他私人联系方式。</p><label class="profile-field">物品名称<input v-model="listingDraft.title" maxlength="80" placeholder="例如：工程制图尺套装"></label><label class="profile-field">分类<select v-model="listingDraft.tag"><option>教材资料</option><option>学习用品</option><option>生活好物</option><option>运动户外</option></select></label><label class="profile-field">价格（元）<input v-model="listingDraft.price" type="number" min="0" max="100000" placeholder="可议价"></label><label class="profile-field">公共交接地点<input v-model="listingDraft.place" maxlength="100" placeholder="例如：图书馆门口"></label><label class="profile-field">物品说明<textarea v-model="listingDraft.description" maxlength="500" rows="3" placeholder="成色、使用情况等"></textarea></label><button class="primary-button full" :disabled="postingListing" @click="createListing">{{postingListing?'正在发布…':'发布闲置'}} <span>→</span></button></div></template><template v-else-if="modal==='contact'"><div class="public-profile"><div class="public-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[selectedUser?.avatarTone||'sunshine']}" alt="奶龙头像"></div><span class="section-kicker">演示用户资料</span><h2 id="modal-title">{{selectedUser?.name}}</h2><p class="profile-meta">{{selectedUser?.faculty}} · {{selectedUser?.year}}</p><p class="profile-bio">{{selectedUser?.bio}}</p><div class="profile-interests"><b>兴趣</b><span>{{selectedUser?.interests}}</span></div><div class="profile-interests"><b>当前状态</b><span>{{selectedUser?.status}} · {{selectedUser?.area}}</span></div><div class="profile-interests"><b>社交状态</b><span :class="['profile-mood',selectedUser?.socialState]">{{selectedUser?.socialState==='low'?'消沉 · 暂不接收邀请':'活跃 · 可接收邀请'}}</span></div><div class="profile-actions"><button class="outline-small" @click="locateUser(selectedUser)">定位同学</button><button class="outline-small" :disabled="selectedUser?.socialState==='low'" @click="inviteProfileUser(selectedUser)">{{selectedUser?.socialState==='low'?'暂不接收邀约':'邀请参加活动'}}</button></div><button class="text-link public-greet" @click="modal='';flash(`已向${selectedUser?.name}打招呼`)">打个招呼 <span>→</span></button></div></template><template v-else><div class="profile-editor"><div class="editor-avatar"><img src="/nailong-avatar.png" :style="{filter:avatarFilters[me.avatarTone]}" alt="奶龙头像预览"></div><span class="section-kicker">MY CAMPUS PROFILE</span><h2 id="modal-title">个人资料与奶龙形象</h2><label class="profile-field">昵称<input v-model="me.name" maxlength="12" placeholder="给自己取个昵称"></label><label class="profile-field">院系<select v-model="me.faculty"><option value="未选择院系">未选择院系</option><option v-for="college in campusColleges" :key="college" :value="college">{{college}}</option><option value="其他 / 待核实">其他 / 待核实</option></select><small class="field-note">列出校方2026年公开报道中点名的常州校区学院（非完整名单）；其他归属请以学校最新信息为准。</small></label><label class="profile-field">年级与身份<input v-model="me.year" maxlength="20" placeholder="例如：2024级 · 本科生（演示）"></label><label class="profile-field">个人简介<textarea v-model="me.bio" maxlength="80" rows="2" placeholder="介绍一下自己"></textarea></label><label class="profile-field">兴趣爱好<input v-model="me.interests" maxlength="40" placeholder="用顿号分隔"></label><div class="tone-picker"><b>奶龙配色</b><div><button v-for="tone in [['sunshine','阳光黄','#f2c94c'],['lagoon','湖水蓝','#77a5ad'],['mint','薄荷绿','#91aa7b'],['peach','蜜桃橙','#e7a56e']]" :key="tone[0]" :class="{selected:me.avatarTone===tone[0]}" @click="me.avatarTone=tone[0]"><i :style="{background:tone[2]}"></i>{{tone[1]}}</button></div></div><div class="social-setting"><div><b>社交状态</b><small>决定是否接收系统活动和同学邀请</small></div><div class="social-options"><button :class="{chosen:profileMoodDraft==='active'}" @click="setSocialState('active')"><i class="active-dot"></i>活跃</button><button :class="{chosen:profileMoodDraft==='low'}" @click="setSocialState('low')"><i class="low-dot"></i>消沉</button></div><p>{{profileMoodDraft==='low'?'保存后不会收到系统活动或同学邀约。':'保存后可以收到系统活动，也可能收到同学邀约。'}}</p></div><div class="social-setting visibility-setting"><div><b>资料可见范围</b><small>此项在本机演示中保存</small></div><div class="social-options"><button :class="{chosen:me.visibility==='campus'}" @click="me.visibility='campus'">校园同学</button><button :class="{chosen:me.visibility==='private'}" @click="me.visibility='private'">仅自己</button></div></div><button class="primary-button full" @click="saveProfile">保存资料 <span>→</span></button></div></template></div></div>
  <Transition><div v-if="toast&&!modal" class="toast" role="status" aria-live="polite"><span>✓</span>{{toast}}</div></Transition>
 </div>
</template>

